mapper.select:
SELECT CC_EMP.EMP_ID, CC_EMP.EMP_EMAIL, CC_EMP.EMP_PHONENUM, CC_EMP.EMP_NAME, CC_EMP.EMP_BIRTH, CC_EMP.EMP_ACCOUNT_STATUS, CC_EMP.EMP_POSITION, CC_EMP.PW_ERROR_CNT, CC_EMP.EMP_JOIN_DT, CC_EMP.EMP_RETIRE_DT, CC_CODE.CODE_NAME AS ROLE, CC_EMP.DEPARTMENT_ID, CC_DEP.DEPARTMENT_NAME, CC_RANK.RANK_NAME, CC_EMP.DIRECT_BOSS_ID FROM CC_EMP INNER JOIN CC_DEP ON CC_EMP.DEPARTMENT_ID = CC_DEP.DEPARTMENT_ID INNER JOIN CC_RANK ON CC_EMP.RANK_ID = CC_RANK.RANK_ID INNER JOIN CC_CODE ON CC_EMP.ROLE_ID = CC_CODE.CODE_NO WHERE 1=1 AND EMP_RETIRE_DT IS NULL AND EMP_ACCOUNT_STATUS = 'Y'
AND EMP_ID = #{empId}
AND EMP_EMAIL = #{empEmail}

SELECT COUNT(*) FROM CC_EMP WHERE 1=1
AND EMP_ID = #{empId}
AND EMP_EMAIL = #{empEmail}
